CREATE OR REPLACE FUNCTION public.preserve_grammar_source_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.source_submission_id IS NOT NULL THEN
    SELECT user_id INTO NEW.source_owner_user_id FROM writing_submissions WHERE id = NEW.source_submission_id;
  ELSIF TG_OP = 'UPDATE' AND OLD.source_owner_user_id IS NOT NULL THEN
    NEW.source_owner_user_id := OLD.source_owner_user_id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.dictionary_immutable_release()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS (SELECT 1 FROM dictionary_releases WHERE id IN (OLD.release_id, NEW.release_id) AND state = 'validated') THEN
  RAISE EXCEPTION 'immutable_dictionary_release';
 END IF;
 RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.preserve_grammar_source_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.source_submission_id IS NOT NULL THEN
    SELECT user_id INTO NEW.source_owner_user_id FROM writing_submissions WHERE id = NEW.source_submission_id;
  ELSIF TG_OP = 'UPDATE' AND OLD.source_owner_user_id IS NOT NULL THEN
    NEW.source_owner_user_id := OLD.source_owner_user_id;
  END IF;
  RETURN NEW;
END;
$function$
